{
  "status": "SUPPORTED",
  "task_summary": "Identify components in storage, fasten assembly, place tool on table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_object",
        "entity_kind": "OBJECT",
        "function": "The mechanical object on the workbench that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["mechanical assembly", "blocks"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "fastening_part",
        "entity_kind": "OBJECT",
        "function": "The hardware component (screw, bolt, etc.) needed to secure the assembly.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "nut"],
        "required_properties": ["compatible with assembly", "removable"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening part.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["wrench", "screwdriver", "spanner"],
        "required_properties": ["able to turn fasteners"]
      },
      {
        "id": "container",
        "entity_kind": "OBJECT",
        "function": "Closed storage structures where components might be hidden.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet"],
        "required_properties": ["enclosed storage"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the tool must be left after the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "fits_relation",
        "relation": "fits",
        "participant_roles": ["fastening_part", "assembly_object"],
        "required": true
      },
      {
        "id": "operates_relation",
        "relation": "operates_on",
        "participant_roles": ["tool", "assembly_object"],
        "required": true
      },
      {
        "id": "rests_relation",
        "relation": "rests_on",
        "participant_roles": ["tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_operation",
        "operation": "search",
        "participant_roles": ["container", "fastening_part"],
        "operation_count": 3
      },
      {
        "id": "fasten_operation",
        "operation": "fasten",
        "participant_roles": ["tool", "fastening_part", "assembly_object"],
        "operation_count": 1
      },
      {
        "id": "place_operation",
        "operation": "place",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "assembly_object": [
        {"label": "yellow and blue blocks", "visual_description": "rectangular blocks on a black tray"}
      ],
      "container": [
        {"label": "left drawer", "visual_description": "blue drawer under table"},
        {"label": "right drawer", "visual_description": "blue drawer under table"},
        {"label": "cabinet", "visual_description": "blue cabinet behind table"}
      ],
      "workbench": [
        {"label": "table surface", "visual_description": "wooden top of the desk"}
      ]
    },
    "inspectable_regions": [
      {"id": "left_drawer", "label": "left drawer under table", "visual_description": "closed blue drawer with handle", "reason": "potential hiding place for fastening components"},
      {"id": "right_drawer", "label": "right drawer under table", "visual_description": "closed blue drawer with handle", "reason": "potential hiding place for fastening components"},
      {"id": "cabinet", "label": "blue cabinet behind table", "visual_description": "closed tall cabinet with handle", "reason": "potential hiding place for fastening components"}
    ],
    "inspection_order": ["left_drawer", "right_drawer", "cabinet"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
